logic [23:0] base_word;
// Canonical plane bytes become 8x8 tile-major; semantic HUD stays linear.
// Constant division/modulo are combinational architecture, not routed timing proof.
function automatic logic [19:0] physical_byte(input logic [19:0] logical_byte);
 integer unsigned base,width,offset,y,x;
 if(logical_byte>=20'd518400)return logical_byte;
 if(logical_byte<20'd345600)begin base=0;width=720;end
 else if(logical_byte<20'd432000)begin base=345600;width=360;end
 else begin base=432000;width=360;end
 offset=32'(logical_byte)-base;y=offset/width;x=offset%width;
 return 20'(base+((y/8)*(width/8)+x/8)*64+(y%8)*8+x%8);
endfunction
wire [19:0] mapped_addr=physical_byte(req_addr);
